","const SCOPE = "x_274351_finance_0";
const MANAGERS_GROUP_SYS_ID = "69cf0a56d84053107f44360b568500cf";

async function callAjax(method: string, params: Record<string, string> = {}) {
 const searchParams = new URLSearchParams({
 sysparm_processor: "ManageUsersHandler",
 sysparm_name: method,
 sysparm_scope: SCOPE,
 ...params,
 });
 const response = await fetch("/xmlhttp.do?" + searchParams.toString(), {
 headers: {
 "X-UserToken": (window as any).g_ck,
 Accept: "application/json",
 },
 });
 const text = await response.text();
 const parser = new DOMParser();
 const xml = parser.parseFromString(text, "text/xml");
 const answer = xml.querySelector("xml")?.getAttribute("answer") || "";
 return answer ? JSON.parse(answer) : null;
}

/**
 * Make a REST Table API call using XMLHttpRequest (same mechanism as GlideAjax).
 * Returns a Promise with the parsed JSON response.
 */
function tableApiRequest(method: string, url: string): Promise<{ status: number; body: any }> {
 return new Promise((resolve) => {
 const xhr = new XMLHttpRequest();
 xhr.open(method, url, true);
 xhr.setRequestHeader("Accept", "application/json");
 xhr.setRequestHeader("X-UserToken", (window as any).g_ck);
 xhr.onreadystatechange = function () {
 if (xhr.readyState !== 4) return;
 let body: any = null;
 try {
 body = xhr.responseText ? JSON.parse(xhr.responseText) : null;
 } catch {
 body = xhr.responseText;
 }
 resolve({ status: xhr.status, body });
 };
 xhr.send();
 });
}

export async function getGroupMembers() {
 return callAjax("getGroupMembers");
}

export async function searchUsers(query: string) {
 return callAjax("searchUsers", { sysparm_query: query });
}

export async function addUserToGroup(userSysId: string) {
 return callAjax("addUserToGroup", { sysparm_user_sys_id: userSysId });
}

/**
 * Remove a user from the Managers group using the REST Table API via
 * XMLHttpRequest. This bypasses scoped GlideRecord cross-scope restrictions
 * by running under the logged-in user's session and ACL permissions.
 */
export async function removeUserFromGroup(userSysId: string) {
 // Step 1: Find the grmember record by group + user
 const query = encodeURIComponent("group=" + MANAGERS_GROUP_SYS_ID + "^user=" + userSysId);
 const findUrl = "/api/now/table/sys_user_grmember?sysparm_query=" + query + "&sysparm_fields=sys_id&sysparm_limit=1";

 const findResult = await tableApiRequest("GET", findUrl);

 if (findResult.status !== 200 || !findResult.body || !findResult.body.result) {
 return {
 success: false,
 message: "Failed to look up group membership (HTTP " + findResult.status + ").",
 };
 }

 const records = findResult.body.result;
 if (records.length === 0) {
 return { success: false, message: "User is not a member of the group." };
 }

 const grmemberSysId = records[0].sys_id;

 // Step 2: Delete the grmember record
 const deleteUrl = "/api/now/table/sys_user_grmember/" + grmemberSysId;
 const deleteResult = await tableApiRequest("DELETE", deleteUrl);

 if (deleteResult.status !== 204 && deleteResult.status !== 200) {
 const errMsg = deleteResult.body && deleteResult.body.error
 ? deleteResult.body.error.message
 : "HTTP " + deleteResult.status;
 return { success: false, message: "Failed to remove user: " + errMsg };
 }

 return { success: true, message: "User removed from the FinanceMe2.0 Managers group." };
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React, { useState, useRef, useEffect, useCallback } from "react";
import { searchUsers } from "../services/ManageUsersService";
import "./UserSearch.css";

interface User {
 sys_id: string;
 name: string;
 email: string;
 title?: string;
}

interface Props {
 onUserAdded: () => void;
 onAdd: (sysId: string) => Promise<void>;
}

export default function UserSearch({ onUserAdded, onAdd }: Props) {
 const [query, setQuery] = useState("");
 const [results, setResults] = useState<User[]>([]);
 const [showDropdown, setShowDropdown] = useState(false);
 const [searching, setSearching] = useState(false);
 const [adding, setAdding] = useState("");
 const wrapperRef = useRef<HTMLDivElement>(null);
 const inputRef = useRef<HTMLInputElement>(null);
 const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

 const doSearch = useCallback(async (q: string) => {
 if (!q.trim() || q.trim().length < 2) {
 setResults([]);
 setShowDropdown(false);
 return;
 }
 setSearching(true);
 try {
 const data = await searchUsers(q);
 setResults(data || []);
 setShowDropdown(true);
 } catch {
 setResults([]);
 }
 setSearching(false);
 }, []);

 function handleInput(e: React.FormEvent<HTMLDivElement>) {
 const target = e.target as HTMLInputElement;
 if (target.tagName === "INPUT" || target.tagName === "TEXTAREA") {
 const val = target.value;
 setQuery(val);
 if (debounceRef.current) clearTimeout(debounceRef.current);
 debounceRef.current = setTimeout(() => doSearch(val), 300);
 }
 }

 function handleSearchClick() {
 if (debounceRef.current) clearTimeout(debounceRef.current);
 doSearch(query);
 }

 function handleKeyDown(e: React.KeyboardEvent) {
 if (e.key === "Enter") {
 e.preventDefault();
 if (debounceRef.current) clearTimeout(debounceRef.current);
 doSearch(query);
 }
 if (e.key === "Escape") setShowDropdown(false);
 }

 async function handleAdd(user: User) {
 setAdding(user.sys_id);
 setShowDropdown(false);
 await onAdd(user.sys_id);
 setResults(prev => prev.filter(u => u.sys_id !== user.sys_id));
 setQuery("");
 if (inputRef.current) inputRef.current.value = "";
 setAdding("");
 onUserAdded();
 }

 useEffect(() => {
 function onClickOutside(e: MouseEvent) {
 if (wrapperRef.current && !wrapperRef.current.contains(e.target as Node)) {
 setShowDropdown(false);
 }
 }
 document.addEventListener("mousedown", onClickOutside);
 return () => document.removeEventListener("mousedown", onClickOutside);
 }, []);

 return (
 <div ref={wrapperRef} className="user-search-wrapper">
 <div className="user-search-bar" onInput={handleInput} onKeyDown={handleKeyDown}>
 <div className="search-input-wrapper">
 <label className="search-label" htmlFor="user-search-input">Search Users</label>
 <input
 ref={inputRef}
 id="user-search-input"
 className="search-input"
 type="text"
 placeholder="Start typing a name or email..."
 autoComplete="off"
 />
 {searching && <span className="search-spinner">Searching…</span>}
 </div>
 <button
 className="search-btn"
 disabled={!query.trim() || adding !== ""}
 onClick={handleSearchClick}
 >
 Search
 </button>
 </div>

 {showDropdown && results.length > 0 && (
 <ul className="search-dropdown">
 {results.map(user => (
 <li key={user.sys_id} className="dropdown-item" onClick={() => handleAdd(user)}>
 <div className="user-info">
 <span className="user-name">{user.name}</span>
 <span className="user-detail">
 {user.email}{user.title ? ` · ${user.title}` : ""}
 </span>
 </div>
 <span className="add-hint">+ Add</span>
 </li>
 ))}
 </ul>
 )}

 {showDropdown && !searching && query.trim().length >= 2 && results.length === 0 && (
 <div className="search-dropdown">
 <div className="dropdown-empty">No users found matching "{query}"</div>
 </div>
 )}

 {adding && <div className="adding-indicator">Adding user to group…</div>}
 </div>
 );
}
","import React, { useState } from "react";
import "./ManagerList.css";

interface Manager {
 sys_id: string;
 name: string;
 email: string;
}

interface Props {
 managers: Manager[];
 loading: boolean;
 onRemove: (sysId: string) => Promise<void>;
}

export default function ManagerList({ managers, loading, onRemove }: Props) {
 const [removing, setRemoving] = useState("");

 async function handleRemove(sysId: string) {
 setRemoving(sysId);
 await onRemove(sysId);
 setRemoving("");
 }

 if (loading) {
 return <div className="loading-text">Loading managers...</div>;
 }

 if (managers.length === 0) {
 return <div className="empty-text">No managers in the group yet.</div>;
 }

 return (
 <ul className="manager-list">
 {managers.map((manager) => (
 <li key={manager.sys_id} className="manager-item">
 <div className="manager-info">
 <span className="manager-name">{manager.name}</span>
 <span className="manager-email">{manager.email}</span>
 </div>
 <button
 className="remove-btn"
 disabled={removing === manager.sys_id}
 onClick={() => handleRemove(manager.sys_id)}
 >
 {removing === manager.sys_id ? "Removing..." : "Remove"}
 </button>
 </li>
 ))}
 </ul>
 );
}
