","import React, { useEffect, useState, useCallback } from "react";
import UserSearch from "./components/UserSearch";
import ManagerList from "./components/ManagerList";
import {
 getGroupMembers,
 addUserToGroup,
 removeUserFromGroup,
} from "./services/ManageUsersService";
import "./app.css";

interface Manager {
 sys_id: string;
 name: string;
 email: string;
}

export default function App() {
 const [managers, setManagers] = useState<Manager[]>([]);
 const [loading, setLoading] = useState(true);
 const [message, setMessage] = useState({ text: "", type: "" });

 const loadManagers = useCallback(async () => {
 setLoading(true);
 try {
 const data = await getGroupMembers();
 setManagers(data || []);
 } catch {
 setMessage({ text: "Failed to load managers.", type: "error" });
 }
 setLoading(false);
 }, []);

 useEffect(() => {
 loadManagers();
 }, [loadManagers]);

 function showMessage(text: string, type: string) {
 setMessage({ text, type });
 setTimeout(() => setMessage({ text: "", type: "" }), 4000);
 }

 async function handleAdd(sysId: string) {
 try {
 const result = await addUserToGroup(sysId);
 if (result && result.success === false) {
 showMessage(result.message || "Failed to add user.", "error");
 } else {
 showMessage("User added to group successfully.", "success");
 }
 await loadManagers();
 } catch {
 showMessage("Failed to add user to group.", "error");
 }
 }

 async function handleRemove(sysId: string) {
 try {
 const result = await removeUserFromGroup(sysId);
 if (result && result.success === false) {
 showMessage(result.message || "Failed to remove user.", "error");
 } else {
 showMessage("User removed from group.", "success");
 }
 await loadManagers();
 } catch {
 showMessage("Failed to remove user.", "error");
 }
 }

 return (
 <div className="manage-users-app">
 <h1>Manage FinanceMe2.0 Managers</h1>
 {message.text && (
 <div className={`status-message ${message.type}`}>{message.text}</div>
 )}
 <div className="section-card">
 <h2>Add User to Group</h2>
 <UserSearch onUserAdded={loadManagers} onAdd={handleAdd} />
 </div>
 <div className="section-card">
 <h2>Current Managers</h2>
 <ManagerList
 managers={managers}
 loading={loading}
 onRemove={handleRemove}
 />
 </div>
 </div>
 );
}
